#!/usr/bin/env node
/**
 * Material nachtragen (Besitzer 27.10.2026: «Material zur Auswahl … und alle anderen auch nachtragen»).
 *
 * Schreibt das Metafeld `mm-google-shopping.material` (single_line_text_field) bei jedem aktiven Produkt, das noch kein Material zeigt
 * UND dessen Material in einer belegten Quelle steht (lib/material.mjs: Produkttext «Material: …» oder CJ-Datenblatt). Der Theme-Block
 * `lux_spezifikationen` zeigt das Feld als Zeile «Material» in «Spezifikationen & Details»; dasselbe Feld füttert das Merchant-Center-Attribut.
 * Nichts wird erfunden: ohne Quelle bleibt das Produkt leer (siehe Zusammenfassung «keine-quelle»).
 *
 * TROCKENLAUF IST VORGABE. LIVE=1 schreibt (25 Produkte je Aufruf), liest danach eine Stichprobe FRISCH zurück und meldet Abweichungen (Exit 3).
 * Aufruf:  node automation/material_nachtragen.mjs                       (Trockenlauf, eigener Plan je Lauf in /tmp)
 *          LIVE=1 node automation/material_nachtragen.mjs                (schreiben)
 * Umgebung: PLAN=pfad · ROH=pfad (vorhandene Bulk-Datei statt neuer Abfrage) · ROH_AUS=pfad (Bulk-Rohdaten speichern) · CJ_FAKTEN_CACHE=ordner (Vorgabe /tmp/cj_fakten_cache)
 *           LIMIT=n (höchstens n Schreibvorgänge) · ONLY=handle,handle
 * Ein bestehender PLAN bleibt unverändert: nur bytegleiche Pläne sind wiederverwendbar. Für einen neuen Restplan einen neuen Pfad wählen.
 * Der Plan enthält geplante Änderungen, keinen Beleg erfolgreich geschriebener Werte.
 */
import { readFileSync, writeFileSync, existsSync, appendFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { shopifyGql } from './lib/shopify_gql.mjs';
import { shopifyClientSecret } from './lib/shopify_secret.mjs';
import { entscheide, hatMaterial, enZuDe, bereinige, pruefeWert, lederWert } from './lib/material.mjs';

const LIVE = process.env.LIVE === '1';
const PLAN = process.env.PLAN || `/tmp/material_plan_${new Date().toISOString().replace(/[:.]/g, '-')}_${randomUUID()}.jsonl`;
const ROH = process.env.ROH || '';
const CJ_ORDNER = (process.env.CJ_FAKTEN_CACHE || '/tmp/cj_fakten_cache').replace(/\/?$/, '/');
const LIMIT = Number(process.env.LIMIT || 1e9);
const ONLY = new Set((process.env.ONLY || '').split(',').map(s => s.trim()).filter(Boolean));
const BELEGE = existsSync('dropship/material_belege.json') ? JSON.parse(readFileSync('dropship/material_belege.json', 'utf8')) : {};
const schlaf = ms => new Promise(r => setTimeout(r, ms));

// Exklusiv anlegen: auch ein gleichzeitiger Lauf darf keinen früheren Plan ersetzen.
function sicherePlan(datei, inhalt) {
  try { writeFileSync(datei, inhalt, { flag: 'wx' }); }
  catch (e) {
    if (e.code !== 'EEXIST') throw e;
    if (readFileSync(datei, 'utf8') !== inhalt) throw new Error('Plandatei bleibt unverändert: ' + datei + '. Für den neuen Plan einen neuen PLAN-Pfad wählen.');
  }
}

async function main() {
  const SHOP = process.env.SHOPIFY_SHOP, CS = shopifyClientSecret(process.env.SHOPIFY_CLIENT_SECRET);
  const r = await fetch(`https://${SHOP}/admin/oauth/access_token`, { method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ client_id: process.env.SHOPIFY_CLIENT_ID, client_secret: CS, grant_type: 'client_credentials' }) });
  const tok = (await r.json()).access_token; if (!tok) throw new Error('Kein Shopify-Token');
  const q = (a, b) => shopifyGql(SHOP, '2025-01', tok, a, b);

  let text;
  if (ROH && existsSync(ROH)) text = readFileSync(ROH, 'utf8');
  else {
    const lauf = (await q(`{currentBulkOperation(type:QUERY){status}}`)).currentBulkOperation;
    if (lauf && ['CREATED', 'RUNNING'].includes(lauf.status)) throw new Error('Es läuft schon eine Bulk-Abfrage — abwarten');
    const inner = `{ products(query:"status:active") { edges { node { id handle title descriptionHtml options{ name } m:metafield(namespace:"mm-google-shopping", key:"material"){ value } } } } }`;
    const m = (await q(`mutation($q:String!){bulkOperationRunQuery(query:$q){bulkOperation{id} userErrors{message}}}`, { q: inner })).bulkOperationRunQuery;
    if (m.userErrors?.length) throw new Error(JSON.stringify(m.userErrors));
    for (let i = 0; i < 360; i++) {
      await schlaf(10000);
      const s = (await q(`{currentBulkOperation(type:QUERY){status errorCode objectCount url}}`)).currentBulkOperation;
      if (s.status === 'COMPLETED') { text = await (await fetch(s.url)).text(); break; }
      if (['FAILED', 'CANCELED', 'EXPIRED'].includes(s.status)) throw new Error('Bulk ' + s.status + ' ' + s.errorCode);
    }
    if (!text) throw new Error('Bulk-Abfrage dauert zu lange');
  }

  if (process.env.ROH_AUS) writeFileSync(process.env.ROH_AUS, text);   // Rohdaten für weitere Trockenläufe ohne neue Bulk-Abfrage (ROH=…)
  const z = { gelesen: 0 }, gruende = {}, werte = {}, plan = [], unbekannt = {};
  for (const l of text.split('\n').filter(Boolean)) {
    const o = JSON.parse(l); if (!o.handle) continue;
    if (ONLY.size && !ONLY.has(o.handle)) continue;
    z.gelesen++;
    const datei = CJ_ORDNER + o.handle + '.json';
    const cj = existsSync(datei) ? JSON.parse(readFileSync(datei, 'utf8')) : null;
    // Schon ein Metafeld: nur englische Werte («Silver», «Alloy», «Cotton») ins Deutsche setzen; deutsche bleiben unberührt
    const vorhanden = String(o.m?.value || '').trim();
    if (vorhanden) {
      const cjL = existsSync(CJ_ORDNER + o.handle + '.json') ? JSON.parse(readFileSync(CJ_ORDNER + o.handle + '.json', 'utf8')) : null;
      // «Leather» (CJ-Grobfeld) nur mit Beleg übersetzen; ohne Beleg bleibt der Wert, wie er ist
      const de = /^leather$/i.test(vorhanden) ? lederWert({ titel: o.title, descriptionHtml: o.descriptionHtml, cj: cjL }) : enZuDe(vorhanden);
      if (/^leather$/i.test(vorhanden) && !de) gruende['leder-ohne-beleg'] = (gruende['leder-ohne-beleg'] || 0) + 1;
      if (de && de.toLowerCase() !== vorhanden.toLowerCase()) {
        const sperre = pruefeWert(de, { descriptionHtml: o.descriptionHtml, titel: o.title, cj: cjL }, { uebersetzung: true });
        if (sperre) gruende['sperre-uebersetzung'] = (gruende['sperre-uebersetzung'] || 0) + 1;
        else { plan.push({ id: o.id, handle: o.handle, wert: de, alt: vorhanden, quelle: 'uebersetzt' }); werte[de] = (werte[de] || 0) + 1; }
      } else if (!de && !bereinige(vorhanden)) unbekannt[vorhanden] = (unbekannt[vorhanden] || 0) + 1;
      if (!(de && de.toLowerCase() !== vorhanden.toLowerCase())) gruende['schon-da:metafeld'] = (gruende['schon-da:metafeld'] || 0) + 1;
      continue;
    }
    let e = entscheide({ descriptionHtml: o.descriptionHtml, optionen: o.options, metafeld: o.m?.value, cj, titel: o.title });
    // Von Hand belegte Angaben (dropship/material_belege.json) gelten, wenn die Seite sonst noch kein Material zeigt
    if (!e.tun && BELEGE[o.handle]?.wert && !hatMaterial({ descriptionHtml: o.descriptionHtml, optionen: o.options, metafeld: o.m?.value })) {
      const wert = bereinige(BELEGE[o.handle].wert);
      const sperre = wert ? pruefeWert(wert, { descriptionHtml: o.descriptionHtml, titel: o.title, cj }) : 'kein sicherer Stoffname';
      e = sperre ? { tun: false, grund: 'sperre-beleg:' + sperre } : { tun: true, wert, quelle: 'belegt-von-hand' };
    }
    if (e.tun) { plan.push({ id: o.id, handle: o.handle, wert: e.wert, quelle: e.quelle }); werte[e.wert] = (werte[e.wert] || 0) + 1; }
    else { const g = e.grund.split(':').slice(0, 2).join(':').slice(0, 40); gruende[g.startsWith('schon') ? g : g.split(':')[0]] = (gruende[g.startsWith('schon') ? g : g.split(':')[0]] || 0) + 1; }
  }
  sicherePlan(PLAN, plan.map(p => JSON.stringify(p)).join('\n') + (plan.length ? '\n' : ''));
  const quellen = plan.reduce((a, p) => (a[p.quelle] = (a[p.quelle] || 0) + 1, a), {});
  console.log(JSON.stringify({ ...z, zuSchreiben: plan.length, quellen, ohneEintrag: gruende, verschiedeneWerte: Object.keys(werte).length, plan: PLAN }));
  console.log('bestehende Metafeld-Werte, die weder deutsch noch übersetzbar sind (' + Object.keys(unbekannt).length + '):', Object.entries(unbekannt).sort((x, y) => y[1] - x[1]).slice(0, 40).map(([w, n]) => `${w}×${n}`).join(' | '));
  console.log('häufigste Werte:', Object.entries(werte).sort((a, b) => b[1] - a[1]).slice(0, 25).map(([w, n]) => `${w}×${n}`).join(' | '));
  if (!LIVE) { console.log('Trockenlauf — nichts geschrieben. LIVE=1 zum Schreiben.'); return; }

  const MUT = `mutation($m:[MetafieldsSetInput!]!){ metafieldsSet(metafields:$m){ metafields{ key } userErrors{ field message code } } }`;
  const arbeit = plan.slice(0, LIMIT); let ok = 0, fehler = 0, folge = 0; const geschrieben = [];
  for (let i = 0; i < arbeit.length; i += 25) {
    const stueck = arbeit.slice(i, i + 25);
    const w = (await q(MUT, { m: stueck.map(p => ({ ownerId: p.id, namespace: 'mm-google-shopping', key: 'material', type: 'single_line_text_field', value: p.wert })) })).metafieldsSet;
    const bad = new Set((w.userErrors || []).map(e => Number(String(e.field?.[1] ?? '').replace(/\D/g, '')) ).filter(Number.isFinite));
    if (w.userErrors?.length) { fehler += Math.max(1, bad.size); folge++; console.error('metafieldsSet:', JSON.stringify(w.userErrors).slice(0, 300)); if (folge >= 3) { console.error('3 Fehler in Folge — Abbruch'); break; } }
    else folge = 0;
    stueck.forEach((p, k) => { if (!bad.has(k)) { ok++; geschrieben.push(p); } });
    if ((i / 25) % 20 === 19) console.log(`  … ${ok} geschrieben`);
    await schlaf(250);
  }
  appendFileSync('dropship/material_ledger.txt', `${new Date().toISOString()} · material nachgetragen · ${ok} Produkte (Fehler ${fehler}) · Quellen ${JSON.stringify(quellen)}\n`);

  // Frisch zurücklesen: 25 zufällige geschriebene Produkte
  const probe = geschrieben.slice().sort(() => Math.random() - .5).slice(0, 25); let abw = 0;
  for (const p of probe) {
    const d = await q(`query($id:ID!){product(id:$id){m:metafield(namespace:"mm-google-shopping", key:"material"){value}}}`, { id: p.id });
    if (d.product?.m?.value !== p.wert) { abw++; console.error('ABWEICHUNG', p.handle, JSON.stringify(d.product?.m?.value), 'statt', p.wert); }
  }
  console.log(JSON.stringify({ geschrieben: ok, fehler, stichprobe: probe.length, abweichungen: abw }));
  if (abw) process.exit(3);
}
main().catch(e => { console.error('FEHLER', e.message); process.exit(1); });

#!/usr/bin/env node
// Ausschliesslich lokale Attrappen: keine echten Shopify-/CJ-Zugriffe oder Zugangsdaten.
import assert from 'node:assert/strict';
import { mkdtempSync, mkdirSync, readFileSync, writeFileSync, copyFileSync, existsSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, isAbsolute, join, relative, resolve, sep } from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';

const hier = dirname(fileURLToPath(import.meta.url));
const quelle = resolve(process.argv[2] || join(hier, 'material_nachtragen.mjs'));
const material = resolve(process.argv[3] || join(dirname(quelle), 'lib/material.mjs'));
const testOrdner = process.env.MATERIAL_TEST_TMP || tmpdir();
let ok = 0, fehler = 0;
const becher = { id: 'gid://shopify/Product/1001', handle: 'becher-fixture', title: 'Becher', descriptionHtml: '', options: [], m: { value: 'Ceramic' } };
const tasse = { ...becher, id: 'gid://shopify/Product/1002', handle: 'tasse-fixture' };
const leer = { id: 'gid://shopify/Product/1003', handle: 'leer-fixture', title: 'Muster', descriptionHtml: '', options: [], m: null };

function fixture(produkte = [becher]) {
  mkdirSync(testOrdner, {recursive:true});
  const dir = mkdtempSync(join(testOrdner, 'material-plan-test-'));
  mkdirSync(join(dir, 'automation/lib'), { recursive: true });
  mkdirSync(join(dir, 'dropship'));
  mkdirSync(join(dir, 'cache'));
  // Auch der Standardpfad muss zum isolierten Testordner gehoeren.
  const runner = readFileSync(quelle, 'utf8').replaceAll('/tmp/material_plan', join(dir, 'default_plan'));
  writeFileSync(join(dir, 'automation/material_nachtragen.mjs'), runner);
  copyFileSync(material, join(dir, 'automation/lib/material.mjs'));
  writeFileSync(join(dir, 'automation/lib/shopify_secret.mjs'), 'export const shopifyClientSecret = () => "fixture-secret";\n');
  writeFileSync(join(dir, 'automation/lib/shopify_gql.mjs'), `
import { appendFileSync, readFileSync, writeFileSync } from 'node:fs';
export async function shopifyGql(shop, version, token, query, variables) {
  if (shop !== 'fixture.myshopify.com' || token !== 'fixture-token') throw new Error('Attrappe: unerwarteter Shop/Token');
  appendFileSync(process.env.TEST_CALLS, JSON.stringify({query, variables}) + '\\n');
  const state = JSON.parse(readFileSync(process.env.TEST_STATE, 'utf8'));
  if (query.includes('metafieldsSet(')) {
    for (const m of variables.m) state[m.ownerId] = m.value;
    writeFileSync(process.env.TEST_STATE, JSON.stringify(state));
    return {metafieldsSet:{metafields:variables.m.map(() => ({key:'material'})),userErrors:[]}};
  }
  if (query.startsWith('query($id:ID!)')) return {product:{m:{value:state[variables.id]}}};
  throw new Error('Attrappe: unerwartete GraphQL-Abfrage');
}
`);
  writeFileSync(join(dir, 'netz-gesperrt.mjs'), `
globalThis.fetch = async (url, options) => {
  if (String(url) !== 'https://fixture.myshopify.com/admin/oauth/access_token' || options?.method !== 'POST')
    throw new Error('Testnetz gesperrt');
  return {json: async () => ({access_token:'fixture-token'})};
};
`);
  const roh = join(dir, 'roh.jsonl'), plan = join(dir, 'plan.jsonl');
  const setRoh = rows => writeFileSync(roh, rows.map(p => JSON.stringify(p)).join('\n') + '\n');
  setRoh(produkte);
  writeFileSync(join(dir, 'state.json'), '{}');
  const run = (extra = {}) => {
    // Absichtlich keine reale Umgebung vererben: nur synthetische Zugangswerte.
    const env = { SHOPIFY_SHOP: 'fixture.myshopify.com', SHOPIFY_CLIENT_ID: 'fixture-client', SHOPIFY_CLIENT_SECRET: 'fixture-secret',
      ROH: roh, PLAN: plan, CJ_FAKTEN_CACHE: join(dir, 'cache'), TEST_CALLS: join(dir, 'calls.jsonl'), TEST_STATE: join(dir, 'state.json'), ...extra };
    for (const [k, v] of Object.entries(env)) if (v === undefined) delete env[k];
    const r = spawnSync(process.execPath, ['--import', join(dir, 'netz-gesperrt.mjs'), join(dir, 'automation/material_nachtragen.mjs')], {cwd:dir,env,encoding:'utf8',timeout:10000});
    assert.equal(r.error, undefined, r.error?.message);
    return r;
  };
  const calls = () => existsSync(join(dir, 'calls.jsonl')) ? readFileSync(join(dir, 'calls.jsonl'), 'utf8').trim().split('\n').filter(Boolean).map(JSON.parse) : [];
  return {dir, roh, plan, run, calls, setRoh, close: () => rmSync(dir, {recursive:true, force:true})};
}
function test(name, fn) {
  try { fn(); ok++; console.log('OK ' + name); }
  catch (e) { fehler++; console.error('FEHLER ' + name + ': ' + e.message); }
}
const erfolg = r => assert.equal(r.status, 0, r.stderr + r.stdout);
const inhalt = f => readFileSync(f.plan, 'utf8');
const zusammenfassung = r => JSON.parse(r.stdout.split('\n').find(l => l.startsWith('{') && l.includes('zuSchreiben')));

test('Neuer Trockenlauf sichert den Originalwert und sendet keine Mutation', () => {
  const f = fixture(); try { erfolg(f.run()); const p=JSON.parse(inhalt(f)); assert.equal(p.alt,'Ceramic'); assert.equal(p.wert,'Keramik'); assert.equal(f.calls().length,0); } finally {f.close();}
});
test('Abweichender Folge-Trockenlauf erhaelt bestehenden Plan bytegleich', () => {
  const f = fixture(); try { erfolg(f.run()); const alt=inhalt(f); f.setRoh([tasse]); const r=f.run(); assert.equal(inhalt(f),alt); assert.notEqual(r.status,0); assert.match(r.stderr,/PLAN|Plandatei/); assert.equal(f.calls().length,0); } finally {f.close();}
});
test('Leerer Folge-Trockenlauf kann den alten Rueckgaengig-Beleg nicht loeschen', () => {
  const f = fixture(); try { erfolg(f.run()); const alt=inhalt(f); f.setRoh([{...becher,m:{value:'Keramik'}}]); const r=f.run(); assert.equal(inhalt(f),alt); assert.notEqual(r.status,0); assert.equal(f.calls().length,0); } finally {f.close();}
});
test('Identischer Trockenlauf bleibt wiederholbar ohne Planverlust', () => {
  const f = fixture(); try { erfolg(f.run()); const alt=inhalt(f); erfolg(f.run()); assert.equal(inhalt(f),alt); assert.equal(f.calls().length,0); } finally {f.close();}
});
test('LIVE-Attrappe nach identischem Trockenlauf respektiert LIMIT und alten Plan', () => {
  const f = fixture([becher,tasse]); try { erfolg(f.run()); const alt=inhalt(f); erfolg(f.run({LIVE:'1',LIMIT:'1'})); assert.equal(inhalt(f),alt); const m=f.calls().filter(c=>c.query.includes('metafieldsSet(')); assert.equal(m.length,1); assert.equal(m[0].variables.m.length,1); assert.equal(m[0].variables.m[0].ownerId,becher.id); } finally {f.close();}
});
test('Abweichender LIVE-Plan blockiert vor der ersten Produktmutation', () => {
  const f = fixture(); try { erfolg(f.run()); const alt=inhalt(f); f.setRoh([tasse]); const r=f.run({LIVE:'1'}); assert.equal(inhalt(f),alt); assert.notEqual(r.status,0); assert.equal(f.calls().length,0); } finally {f.close();}
});
test('Fortsetzung mit frischem Rest und neuem Pfad erhaelt beide Originalplaene', () => {
  const f = fixture([becher,tasse]); try {
    erfolg(f.run()); const alt=inhalt(f); erfolg(f.run({LIVE:'1',LIMIT:'1'}));
    f.setRoh([{...becher,m:{value:'Keramik'}},tasse]); const folge=join(f.dir,'rest.jsonl');
    erfolg(f.run({PLAN:folge})); const rest=readFileSync(folge,'utf8');
    erfolg(f.run({PLAN:folge,LIVE:'1'})); assert.equal(inhalt(f),alt); assert.equal(readFileSync(folge,'utf8'),rest);
    const p=JSON.parse(rest); assert.equal(p.id,tasse.id); assert.equal(p.alt,'Ceramic');
    assert.deepEqual(f.calls().filter(c=>c.query.includes('metafieldsSet(')).flatMap(c=>c.variables.m.map(m=>m.ownerId)),[becher.id,tasse.id]);
  } finally {f.close();}
});
test('Verschiedene Standardlaeufe benutzen eindeutige Pfade statt Ueberschreiben', () => {
  const f = fixture(); try {
    const eigenerPfad = p => { const r=relative(f.dir,resolve(p)); assert.ok(r && r!=='..' && !r.startsWith('..'+sep) && !isAbsolute(r),'Planpfad muss im eigenen Fixture bleiben'); return resolve(p); };
    const a=f.run({PLAN:undefined}); erfolg(a); const pa=eigenerPfad(zusammenfassung(a).plan); const alt=readFileSync(pa,'utf8');
    f.setRoh([tasse]); const b=f.run({PLAN:undefined}); erfolg(b); const pb=eigenerPfad(zusammenfassung(b).plan);
    assert.notEqual(pa,pb); assert.equal(readFileSync(pa,'utf8'),alt);
  } finally {f.close();}
});
test('Nicht beschreibbarer Planpfad blockiert vor Produktmutation', () => {
  const f = fixture(); try { const r=f.run({PLAN:join(f.dir,'fehlt','plan.jsonl'),LIVE:'1'}); assert.notEqual(r.status,0); assert.equal(f.calls().length,0); } finally {f.close();}
});
test('Manueller sauberer Materialwert bleibt erlaubt', () => {
  const f = fixture([leer]); try { writeFileSync(join(f.dir,'dropship/material_belege.json'),JSON.stringify({[leer.handle]:{wert:'Keramik'}})); erfolg(f.run()); assert.equal(JSON.parse(inhalt(f)).wert,'Keramik'); } finally {f.close();}
});
for (const wert of ['Seide (Imitat)','Titanstahl']) test('Manueller Override verwirft '+wert, () => {
  const f = fixture([leer]); try { writeFileSync(join(f.dir,'dropship/material_belege.json'),JSON.stringify({[leer.handle]:{wert}})); const r=f.run(); erfolg(r); assert.equal(inhalt(f),''); assert.equal(zusammenfassung(r).ohneEintrag['sperre-beleg'],1); assert.equal(f.calls().length,0); } finally {f.close();}
});
test('Manueller Wert wird kanonisch statt ungeprueft uebernommen', () => {
  const f = fixture([leer]); try { writeFileSync(join(f.dir,'dropship/material_belege.json'),JSON.stringify({[leer.handle]:{wert:'hochwertige Keramik'}})); erfolg(f.run()); assert.equal(JSON.parse(inhalt(f)).wert,'Keramik'); } finally {f.close();}
});
test('Manueller Wert darf einen bekannten Titelkonflikt nicht umgehen', () => {
  const f = fixture([{...leer,title:'Leinen-Kleid'}]); try { writeFileSync(join(f.dir,'dropship/material_belege.json'),JSON.stringify({[leer.handle]:{wert:'Baumwolle'}})); const r=f.run(); erfolg(r); assert.equal(inhalt(f),''); assert.equal(zusammenfassung(r).ohneEintrag['sperre-beleg'],1); } finally {f.close();}
});
test('Manuelle Seide darf den belegten Imitat-Hinweis nicht umgehen', () => {
  const f = fixture([{...leer,descriptionHtml:'<p>Material: Seide (Imitat)</p>'}]); try { writeFileSync(join(f.dir,'dropship/material_belege.json'),JSON.stringify({[leer.handle]:{wert:'Seide'}})); const r=f.run(); erfolg(r); assert.equal(inhalt(f),''); assert.equal(zusammenfassung(r).ohneEintrag['sperre-beleg'],1); } finally {f.close();}
});
test('Uebersetzung beachtet Imitat-Hinweis aus dem vorhandenen CJ-Cache', () => {
  const f = fixture([{...leer,m:{value:'Silk'}}]); try { writeFileSync(join(f.dir,'cache',leer.handle+'.json'),JSON.stringify({description:'<p>Material: silk (imitation)</p>'})); const r=f.run(); erfolg(r); assert.equal(inhalt(f),''); assert.equal(zusammenfassung(r).ohneEintrag['sperre-uebersetzung'],1); assert.equal(f.calls().length,0); } finally {f.close();}
});

console.log(`${ok} ok, ${fehler} Fehler`);
process.exitCode = fehler ? 1 : 0;

#!/usr/bin/env node
/**
 * Zählt den Arbeitsstand aus den Ledgern (nur lesen) und schreibt ihn als JSON-Zeilen für die Fortschrittsseite.
 * Aufruf: node automation/fortschritt_daten.mjs [OUT=/tmp/fortschritt.json]
 * Jede Zahl nennt ihre Quelle (Ledger-Datei). Fehlende/unlesbare Quellen ergeben null, nie 0 oder 100 %.
 * Ledger-Erfolge sind Arbeitsfortschritt, keine aktuelle Vollständigkeitsquote für Farbe, Grösse oder Material.
 */
import { readFileSync, writeFileSync } from 'node:fs';
const OUT = process.env.OUT || '/tmp/fortschritt.json';
const lesefehler = new Map();
const lies = p => {
  try { return readFileSync(p, 'utf8').split('\n').filter(z => z.trim()); }
  catch (e) { lesefehler.set(p, e.code || 'nicht lesbar'); return null; }
};
const unbekannt = (p, grund) => { lesefehler.set(p, grund); return null; };
const zeitpunkt = new Date().toISOString();

const geschrieben = ledger => {
  const zeilen = lies(ledger);
  if (zeilen === null) return null;
  const teile = zeilen.map(z => z.split('·').map(s => s.trim()));
  if (teile.some(([h, zeit, e]) => !h || !Number.isFinite(Date.parse(zeit)) || !e)) return unbekannt(ledger, 'ungültige Ledger-Zeile');
  return new Set(teile.filter(([, , e]) => e === 'GESCHRIEBEN').map(([h]) => h));
};
const kategorien = lies('dropship/kategorien_ledger.txt');
const art = k => kategorien === null ? null : new Set(kategorien.map(z => z.split(' · ')).filter(t => (t[1] || '').split(' ')[0] === k).map(t => (t[1] || '').split(' ')[1]).filter(Boolean));
const anzahl = menge => menge?.size ?? null;
const verengt = () => {
  const pfad = 'automation/lib/kategorien_verengt_daten.json';
  const zeilen = lies(pfad);
  if (zeilen === null) return null;
  try {
    const daten = JSON.parse(zeilen.join('\n'));
    return Array.isArray(daten) ? daten.length : unbekannt(pfad, 'JSON ist keine Liste');
  } catch { return unbekannt(pfad, 'ungültiges JSON'); }
};

const ausw = geschrieben('dropship/cj_varianten_ledger.txt');
const kandidatenpfad = '/tmp/auswahl_kandidaten.csv';
const kandidaten = lies(kandidatenpfad);
const kand = kandidaten === null ? null : kandidaten.some(z => !z.split(';')[0].trim())
  ? unbekannt(kandidatenpfad, 'Kandidat ohne Handle')
  : new Set(kandidaten.map(z => z.split(';')[0].trim()));
// Nachgezogene Produkte verschwinden aus neuen Scans. Nur mit beiden Quellen ist die Vereinigung bekannt.
const pool = kand !== null && ausw !== null ? new Set([...kand, ...ausw]) : null;

const zeilen = [
  { id: 'auswahl', bereich: 'Varianten-Auswahl nachgezogen', einheit: 'Produkte', fertig: anzahl(ausw), gesamt: anzahl(pool), quelle: 'cj_varianten_ledger.txt + Kandidatenliste vom Katalog-Scan', anmerkung: 'Arbeitsvorrat aus Kandidaten und belegten Schreib-Erfolgen, keine Katalogquote. Ein Teil führt bei CJ wirklich nur eine Variante; übersprungen und SKU_GESETZT zählen nicht als nachgezogene Auswahl' },
  { id: 'varbilder', bereich: 'Variantenbilder verknüpft', einheit: 'Produkte', fertig: anzahl(geschrieben('dropship/cj_variantenbilder_ledger.txt')), gesamt: 890, quelle: 'cj_variantenbilder_ledger.txt', anmerkung: 'Umfang gemessen am 25.10. an den neuesten 2010 CJ-Produkten' },
  { id: 'texte', bereich: 'Ausführliche Produkttexte', einheit: 'Produkte', fertig: anzahl(art('text-v2')), gesamt: null, quelle: 'kategorien_ledger.txt (text-v2)', anmerkung: 'nur Produkte mit lesbarem CJ-Datenblatt; Umfang nicht gemessen' },
  { id: 'fakten', bereich: 'Technische Daten, Lieferumfang', einheit: 'Produkte', fertig: anzahl(art('fakten')), gesamt: null, quelle: 'kategorien_ledger.txt (fakten)', anmerkung: 'nur belegte Angaben aus dem Datenblatt' },
  { id: 'labels', bereich: 'Kategorie-Bilder', einheit: 'Kategorien', fertig: anzahl(art('bild')), gesamt: 88, quelle: 'kategorien_ledger.txt (bild)', anmerkung: '88 Kategorien in lib/kategorien.mjs' },
  { id: 'bewertung', bereich: 'Gut bewertete zuerst', einheit: 'Kategorien', fertig: anzahl(art('bewertung-zuerst')), gesamt: null, quelle: 'kategorien_ledger.txt (bewertung-zuerst)', anmerkung: 'Kategorien im Menü mit mindestens 10 Produkten' },
  { id: 'optionen', bereich: 'Optionswerte ins Deutsche', einheit: 'Produkte', fertig: anzahl(art('optionen-uebersetzt')), gesamt: 2863, quelle: 'kategorien_ledger.txt (optionen-uebersetzt)', anmerkung: 'Umfang gemessen am 26.10. (2 863 Produkte mit englischen Werten); ein Teil bleibt bewusst englisch (Namenskollision, Zahl, Marke)' },
  { id: 'verengt', bereich: 'Menü-Seiten ohne Fremdprodukte', einheit: 'Kategorien', fertig: verengt(), gesamt: 27, quelle: 'lib/kategorien_verengt_daten.json (live am 26.10.)', anmerkung: '27 Alt-Collections von Titel-Regeln auf Tags mit Google-Kategorie-Ausschlüssen umgestellt; Prüfer-Ausreisser 631 → 315' },
  { id: 'titel', bereich: 'Titel korrigiert', einheit: 'Produkte', fertig: anzahl(art('titel')), gesamt: null, quelle: 'kategorien_ledger.txt (titel)', anmerkung: 'Titel, die dem Datenblatt widersprachen' },
].map(z => ({ ...z, stand: zeitpunkt }));
writeFileSync(OUT, JSON.stringify(zeilen, null, 1));
console.log(zeilen.map(z => `${z.bereich}: ${z.fertig ?? 'unbekannt'} / ${z.gesamt ?? 'unbekannt'}`).join('\n'));
for (const [pfad, grund] of lesefehler) console.error(`Quelle unbekannt: ${pfad} (${grund})`);

#!/usr/bin/env node
// Blackbox-Gegenproben: echte Berichtdatei, alle Datei-Zugriffe durch isolierte Attrappen ersetzt.
// Kein Shop, Netz, /tmp-Kandidatenbestand oder echtes Ledger wird gelesen/geschrieben.
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

const ziel = process.env.FORTSCHRITT_TEST_TARGET || fileURLToPath(new URL('./fortschritt_daten.mjs', import.meta.url));
const bootstrap = String.raw`
  import fs from 'node:fs';
  import { syncBuiltinESMExports } from 'node:module';
  const input = JSON.parse(fs.readFileSync(0, 'utf8'));
  const quelltext = fs.readFileSync(input.ziel, 'utf8');
  const ausgaben = {}, logs = [], warnungen = [];
  fs.existsSync = p => Object.hasOwn(input.dateien, p);
  fs.readFileSync = p => {
    const wert = input.dateien[p];
    if (!Object.hasOwn(input.dateien, p) || typeof wert !== 'string') {
      const e = new Error('Testquelle nicht lesbar'); e.code = wert?.code || 'ENOENT'; throw e;
    }
    return wert;
  };
  fs.writeFileSync = (p, inhalt) => { ausgaben[p] = inhalt; };
  syncBuiltinESMExports();
  console.log = (...s) => logs.push(s.join(' '));
  console.error = (...s) => warnungen.push(s.join(' '));
  process.env.OUT = '/virtuell/fortschritt.json';
  let fehler = null;
  try { await import('data:text/javascript;base64,' + Buffer.from(quelltext).toString('base64')); } catch (e) { fehler = e.message; }
  process.stdout.write(JSON.stringify({ zeilen: ausgaben[process.env.OUT] ? JSON.parse(ausgaben[process.env.OUT]) : null, logs, warnungen, fehler }));
`;
const ledger = 'dropship/cj_varianten_ledger.txt';
const kandidaten = '/tmp/auswahl_kandidaten.csv';
const bilder = 'dropship/cj_variantenbilder_ledger.txt';
const kategorien = 'dropship/kategorien_ledger.txt';
const verengt = 'automation/lib/kategorien_verengt_daten.json';
const zeit = '2026-10-28T10:00:00.000Z';
const zeile = (h, status, grund = 'Test') => `${h} · ${zeit} · ${status} · ${grund}`;
const grundlage = () => ({
  [ledger]: [zeile('fertig', 'GESCHRIEBEN'), zeile('fertig', 'GESCHRIEBEN'), zeile('solo', 'UEBERSPRUNGEN', 'CJ führt nur 1 Variante — kein Auswahlproblem'), zeile('sku', 'SKU_GESETZT'), zeile('fehler', 'FEHLER')].join('\n'),
  [kandidaten]: 'offen;1;CJ-123;3;123\nfertig;2;CJ-456;2;456\noffen;1;CJ-123;3;123\n',
  [bilder]: zeile('bild-a', 'GESCHRIEBEN'),
  [kategorien]: `${zeit} · text-v2 text-a\n${zeit} · text-v2 text-a\n${zeit} · optionen-uebersetzt text-b\n${zeit} · fakten text-c\n`,
  [verengt]: '[{"handle":"kategorie-a"}]',
});
function lauf(dateien) {
  const p = spawnSync(process.execPath, ['--input-type=module', '--eval', bootstrap], { input: JSON.stringify({ ziel, dateien }), encoding: 'utf8', timeout: 10000, env: { PATH: process.env.PATH } });
  assert.equal(p.status, 0, p.stderr || p.error?.message);
  const r = JSON.parse(p.stdout);
  assert.equal(r.fehler, null, r.fehler);
  assert.equal(r.zeilen.length, 9);
  return r;
}
const auswahl = r => r.zeilen.find(z => z.id === 'auswahl');
let ok = 0, fehler = 0;
function pruefe(name, test) { try { test(); ok++; console.log(`ok ${name}`); } catch (e) { fehler++; console.error(`FEHLER ${name}: ${e.message}`); } }

pruefe('Vereinigung zählt frühere Erfolge und aktuelle Kandidaten genau einmal', () => {
  const r = lauf(grundlage());
  assert.equal(auswahl(r).fertig, 1);
  assert.equal(auswahl(r).gesamt, 2);
  assert.equal(r.zeilen.find(z => z.id === 'texte').fertig, 1);
  assert.equal(r.zeilen.find(z => z.id === 'optionen').fertig, 1);
  assert.deepEqual(r.warnungen, []);
});
pruefe('Fehlende Kandidatenliste ergibt unbekannten Nenner statt falscher 100 %', () => {
  const d = grundlage(); delete d[kandidaten]; const r = lauf(d);
  assert.equal(auswahl(r).fertig, 1); assert.equal(auswahl(r).gesamt, null);
  assert.match(r.logs.join('\n'), /1 \/ unbekannt/);
  assert.match(r.warnungen.join('\n'), /auswahl_kandidaten.csv.*ENOENT/);
});
pruefe('Unlesbare Kandidaten sind unbekannt; übrige Bereiche bleiben messbar', () => {
  const d = grundlage(); d[kandidaten] = { code: 'EACCES' }; const r = lauf(d);
  assert.equal(auswahl(r).gesamt, null); assert.equal(r.zeilen.find(z => z.id === 'varbilder').fertig, 1);
  assert.match(r.warnungen.join('\n'), /EACCES/);
});
pruefe('Fehlendes Ledger ist kein Null-Erfolg und liefert keinen vollständigen Pool', () => {
  const d = grundlage(); delete d[ledger]; const r = lauf(d);
  assert.equal(auswahl(r).fertig, null); assert.equal(auswahl(r).gesamt, null);
});
pruefe('Leere vorhandene Quellen ergeben belegte Nullen', () => {
  const d = grundlage(); d[ledger] = ''; d[kandidaten] = '\n  \n'; const r = lauf(d);
  assert.equal(auswahl(r).fertig, 0); assert.equal(auswahl(r).gesamt, 0);
  assert.match(r.logs.join('\n'), /0 \/ 0/); assert.deepEqual(r.warnungen, []);
});
pruefe('Leerer neuer Scan erhält schon nachgezogene Produkte im Pool', () => {
  const d = grundlage(); d[kandidaten] = ''; const r = lauf(d);
  assert.equal(auswahl(r).fertig, 1); assert.equal(auswahl(r).gesamt, 1);
});
pruefe('SKU-Geändert, Einvarianten-Skip und Fehler sind kein Auswahl-Erfolg', () => {
  const d = grundlage(); d[ledger] = [zeile('solo', 'UEBERSPRUNGEN'), zeile('sku', 'SKU_GESETZT'), zeile('fehler', 'FEHLER')].join('\n'); const r = lauf(d);
  assert.equal(auswahl(r).fertig, 0); assert.equal(auswahl(r).gesamt, 2);
});
pruefe('Beschädigtes Ledger ergibt unbekannt statt Teilzählung', () => {
  const d = grundlage(); d[ledger] += '\nunvollständig'; const r = lauf(d);
  assert.equal(auswahl(r).fertig, null); assert.equal(auswahl(r).gesamt, null);
  assert.match(r.warnungen.join('\n'), /ungültige Ledger-Zeile/);
});
pruefe('Kandidat ohne Handle ergibt unbekannt statt Phantomprodukt', () => {
  const d = grundlage(); d[kandidaten] += ';1;CJ-999;1;999\n'; const r = lauf(d);
  assert.equal(auswahl(r).gesamt, null);
});
pruefe('Fehlende weitere Ledger bleiben unbekannt, Auswahl unverändert', () => {
  const d = grundlage(); delete d[bilder]; delete d[kategorien]; const r = lauf(d);
  for (const id of ['varbilder', 'texte', 'fakten', 'labels', 'bewertung', 'optionen', 'titel']) assert.equal(r.zeilen.find(z => z.id === id).fertig, null, id);
  assert.equal(auswahl(r).fertig, 1);
});
pruefe('Fehlende oder beschädigte JSON-Daten blockieren keine unabhängigen Zahlen', () => {
  for (const wert of [undefined, '{kaputt', '{}']) {
    const d = grundlage(); if (wert === undefined) delete d[verengt]; else d[verengt] = wert; const r = lauf(d);
    assert.equal(r.zeilen.find(z => z.id === 'verengt').fertig, null); assert.equal(auswahl(r).fertig, 1);
  }
});
pruefe('Anmerkung bezeichnet Arbeitsvorrat und keine Katalog-Vollständigkeit', () => {
  const a = auswahl(lauf(grundlage()));
  assert.match(a.anmerkung, /keine Katalogquote/);
  assert.match(a.anmerkung, /SKU_GESETZT zählen nicht/);
});

console.log(`${ok} ok, ${fehler} Fehler`);
process.exitCode = fehler ? 1 : 0;
